// Keyword filter + budget parsing + dedupe. Runs once for all RSS items.
const cfg = $('Config').first().json;
const keywords = (cfg.keywords || []).map((k) => String(k).toLowerCase());
const minBudget = Number(cfg.minBudget) || 0;
const MAX_SEEN = 2000;

const store = $getWorkflowStaticData('global');
store.seenGuids = Array.isArray(store.seenGuids) ? store.seenGuids : [];
const seen = new Set(store.seenGuids);

const stripHtml = (s) => String(s || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/[ \t]+/g, ' ')
  .trim();

// Returns { type: 'fixed'|'hourly'|'unknown', min, max, label }
const parseBudget = (text) => {
  const fixed = text.match(/budget\s*:?\s*\$\s*([\d,]+(?:\.\d+)?)/i);
  if (fixed) {
    const v = Number(fixed[1].replace(/,/g, ''));
    return { type: 'fixed', min: v, max: v, label: `$${v} fixed` };
  }
  const hourly = text.match(/hourly(?:\s*range)?\s*:?\s*\$\s*([\d,]+(?:\.\d+)?)\s*(?:-|–|to)\s*\$?\s*([\d,]+(?:\.\d+)?)/i);
  if (hourly) {
    const lo = Number(hourly[1].replace(/,/g, ''));
    const hi = Number(hourly[2].replace(/,/g, ''));
    return { type: 'hourly', min: lo, max: hi, label: `$${lo}-$${hi}/hr` };
  }
  return { type: 'unknown', min: null, max: null, label: 'not specified' };
};

const out = [];
for (const item of $input.all()) {
  const job = item.json;
  const guid = String(job.guid || job.link || job.title || '');
  if (!guid || seen.has(guid)) continue;

  const title = String(job.title || '');
  const description = stripHtml(job.content || job.contentSnippet || job.description || '');
  const haystack = `${title}\n${description}`.toLowerCase();
  const matched = keywords.filter((k) => haystack.includes(k));

  // Mark as seen regardless of the outcome so we never re-process the same post.
  seen.add(guid);
  store.seenGuids.push(guid);
  if (matched.length === 0) continue;

  const budget = parseBudget(description);
  // Hourly jobs are compared on the max rate * 10h as a rough floor; unknown budgets pass through.
  const comparable = budget.type === 'fixed' ? budget.min : budget.type === 'hourly' ? budget.max * 10 : null;
  if (comparable !== null && comparable < minBudget) continue;

  out.push({
    json: {
      guid,
      title,
      link: job.link || '',
      publishedAt: job.isoDate || job.pubDate || '',
      description: description.slice(0, 3000),
      matchedKeywords: matched,
      budget,
      promptText: `Job title: ${title}\nBudget: ${budget.label}\nMatched keywords: ${matched.join(', ')}\n\nDescription:\n${description.slice(0, 3000)}`,
    },
  });
}

if (store.seenGuids.length > MAX_SEEN) store.seenGuids = store.seenGuids.slice(-MAX_SEEN);
return out;

