// Parse Claude's JSON answer and merge it back onto the job.
const job = $('Filter, Parse Budget, Dedupe').item.json;
const resp = $json || {};

let fit = 0;
let reasons = [];
let scoringError = null;

if (resp.error) {
  scoringError = typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error));
} else {
  const textBlock = Array.isArray(resp.content) ? resp.content.find((b) => b.type === 'text') : null;
  const raw = (textBlock?.text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    const parsed = JSON.parse(start >= 0 && end > start ? raw.slice(start, end + 1) : raw);
    fit = Math.max(0, Math.min(10, Math.round(Number(parsed.fit) || 0)));
    reasons = Array.isArray(parsed.reasons) ? parsed.reasons.map(String).slice(0, 5) : [];
  } catch (e) {
    scoringError = `parse_error: ${e.message}`;
    reasons = ['parse_error'];
  }
}

return {
  json: {
    ...job,
    fit,
    reasons,
    scoringError,
    usage: resp.usage || null,
  },
};
